import{_ as t}from"./chunks/image 2.Dyzhk9-H.js";import{_ as r,o as e,c as l,a3 as o}from"./chunks/framework.Bh_aNVBG.js";const i="/images/partner/image.png",n="/images/partner/image%201.png",s="/images/partner/image%203.png",f=JSON.parse('{"title":"2. CMS 시작하기","description":"","frontmatter":{},"headers":[],"relativePath":"partner/chapter-2.md","filePath":"partner/chapter-2.md"}'),p={name:"partner/chapter-2.md"};function h(c,a,d,m,_,g){return e(),l("div",null,[...a[0]||(a[0]=[o('<h1 id="_2-cms-시작하기" tabindex="-1">2. CMS 시작하기 <a class="header-anchor" href="#_2-cms-시작하기" aria-label="Permalink to &quot;2. CMS 시작하기&quot;">​</a></h1><h2 id="_2-1-cms-접속-및-로그인" tabindex="-1">2.1. CMS 접속 및 로그인 <a class="header-anchor" href="#_2-1-cms-접속-및-로그인" aria-label="Permalink to &quot;2.1. CMS 접속 및 로그인&quot;">​</a></h2><p>인포디오 CMS는 웹 브라우저를 통해 접속할 수 있는 관리자 페이지입니다.</p><p>파트너는 프로젝트별로 제공된 CMS 접속 주소를 이용하여 해당 프로젝트의 공지사항 관리 및 스탬프 투어 보상 지급 업무를 수행할 수 있습니다.</p><h3 id="_1-cms-접속" tabindex="-1">① CMS 접속 <a class="header-anchor" href="#_1-cms-접속" aria-label="Permalink to &quot;① CMS 접속&quot;">​</a></h3><ol><li>Chrome, Edge 등 웹 브라우저를 실행합니다.</li><li>전달받은 프로젝트별 CMS 접속 주소를 주소창에 입력합니다.</li><li>인포디오 CMS 로그인 화면이 표시됩니다.</li></ol><p><strong>접속 주소 예시</strong></p><p><a href="https://infodio.kr/cms/?slug=2026smf" target="_blank" rel="noreferrer">https://infodio.kr/cms/?slug=2026smf</a></p><p><img src="'+i+'" alt="image.png"></p><blockquote><p><strong>참고</strong></p><p>CMS 접속 주소는 프로젝트별로 다르게 제공됩니다.</p><p>반드시 행사 운영 담당자로부터 전달받은 접속 주소를 이용해 주세요.</p></blockquote><h3 id="_2-로그인" tabindex="-1">② 로그인 <a class="header-anchor" href="#_2-로그인" aria-label="Permalink to &quot;② 로그인&quot;">​</a></h3><ol><li><strong>Email</strong> 입력란에 발급받은 파트너 계정의 이메일을 입력합니다.</li><li><strong>Password</strong> 입력란에 비밀번호를 입력합니다.</li><li><strong>로그인</strong> 버튼을 클릭합니다.</li><li>로그인이 완료되면 해당 프로젝트의 관리 화면으로 이동합니다.</li></ol><blockquote><p><strong>참고</strong></p><ul><li>파트너 계정은 관리자를 통해 발급됩니다.</li><li>로그인 정보가 올바르지 않은 경우 오류 메시지가 표시됩니다.</li><li>계정 관련 문의는 고객지원(<a href="mailto:support@infodio.kr" target="_blank" rel="noreferrer">support@infodio.kr</a>)으로 연락해 주세요.</li></ul></blockquote><hr><h2 id="_2-2-비밀번호-재설정" tabindex="-1">2.2. 비밀번호 재설정 <a class="header-anchor" href="#_2-2-비밀번호-재설정" aria-label="Permalink to &quot;2.2. 비밀번호 재설정&quot;">​</a></h2><p>비밀번호를 잊어버린 경우, 로그인 화면에서 이메일 인증을 통해 비밀번호를 재설정할 수 있습니다.</p><h3 id="_1-비밀번호-재설정-요청" tabindex="-1">① 비밀번호 재설정 요청 <a class="header-anchor" href="#_1-비밀번호-재설정-요청" aria-label="Permalink to &quot;① 비밀번호 재설정 요청&quot;">​</a></h3><ol><li>CMS 로그인 화면으로 이동합니다.</li><li><strong>메일로 비밀번호 재설정 링크 전송</strong> 버튼을 클릭합니다.</li><li>비밀번호 재설정 창이 표시되면 계정에 등록된 이메일 주소를 입력합니다.</li><li><strong>전송</strong> 버튼을 클릭합니다.</li><li>입력한 이메일로 발송된 비밀번호 재설정 안내 메일을 확인합니다.</li></ol><p><img src="'+n+'" alt="image.png"></p><h3 id="_2-새-비밀번호-설정" tabindex="-1">② 새 비밀번호 설정 <a class="header-anchor" href="#_2-새-비밀번호-설정" aria-label="Permalink to &quot;② 새 비밀번호 설정&quot;">​</a></h3><ol><li>수신한 이메일에서 비밀번호 재설정 링크를 클릭합니다.</li><li>새로운 비밀번호를 입력합니다.</li><li>비밀번호 확인란에 동일한 비밀번호를 다시 입력합니다.</li><li><strong>확인</strong> 버튼을 클릭하여 변경을 완료합니다.</li><li>로그인 화면으로 돌아가 변경한 비밀번호로 로그인합니다.</li></ol><p>비밀번호는 다음 조건을 충족해야 합니다.</p><ul><li>6~20자</li><li>영문 대문자 및 소문자 포함</li><li>숫자 포함</li><li>특수문자 포함</li></ul><blockquote><p><strong>주의사항</strong></p><p>비밀번호 재설정 이메일이 도착하지 않는 경우 스팸 메일함을 확인해 주세요. 등록되지 않은 이메일이거나 문제가 지속되는 경우 관리자에게 문의해 주세요.</p></blockquote><hr><h2 id="_2-3-파트너-화면" tabindex="-1">2.3. 파트너 화면 <a class="header-anchor" href="#_2-3-파트너-화면" aria-label="Permalink to &quot;2.3. 파트너 화면&quot;">​</a></h2><p>CMS에 로그인하면 해당 프로젝트의 화면이 표시됩니다.</p><p>파트너 관리 화면에서는 공지사항 관리 및 스탬프 투어 보상 지급 업무를 수행할 수 있습니다.</p><h3 id="_1-화면-구성" tabindex="-1">① 화면 구성 <a class="header-anchor" href="#_1-화면-구성" aria-label="Permalink to &quot;① 화면 구성&quot;">​</a></h3><p><img src="'+t+'" alt="image.png"></p><p><img src="'+s+'" alt="image.png"></p><h3 id="_2-주요-관리-기능" tabindex="-1">② 주요 관리 기능 <a class="header-anchor" href="#_2-주요-관리-기능" aria-label="Permalink to &quot;② 주요 관리 기능&quot;">​</a></h3><table tabindex="0"><thead><tr><th>관리 영역</th><th>주요 기능</th></tr></thead><tbody><tr><td>공지사항</td><td>행사 운영과 관련된 공지사항 등록 및 관리</td></tr><tr><td>스탬프 투어 보상 수령</td><td>방문객의 보상 수령 QR 코드 스캔</td></tr></tbody></table><blockquote><p><strong>참고</strong></p><p>파트너 계정은 부여된 권한 내에서만 관리 기능을 이용할 수 있습니다.</p><p>프로젝트 설정 및 기타 콘텐츠의 변경이 필요한 경우 행사 운영 담당자에게 문의해 주세요.</p></blockquote><p>각 기능의 세부 이용 방법은 이후 각 장에서 안내합니다.</p>',35)])])}const q=r(p,[["render",h]]);export{f as __pageData,q as default};
